const compRows = $('Calcular Planejado x Realizado1').all().map(i => i.json);
const lancRows = $input.all().map(i => i.json);
const trigger = $('When Executed by Another Workflow').item.json;

function formatBRL(n) {
  return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatDate(iso) {
  const d = new Date(iso);
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  return `${dd}/${mm}`;
}

// Agrupa lançamentos por category_id, já ordenados do mais recente pro mais antigo
const porCategoria = {};
for (const r of lancRows) {
  if (!porCategoria[r.category_id]) porCategoria[r.category_id] = [];
  porCategoria[r.category_id].push(r);
}

const detalhamentoPorCategoria = {};
for (const [catId, itens] of Object.entries(porCategoria)) {
  const linhas = itens.map(i => `- **${formatDate(i.date)}**: **R$ ${formatBRL(Number(i.value))}** - ${i.description}`);
  const total = itens.reduce((acc, i) => acc + Number(i.value), 0);
  detalhamentoPorCategoria[catId] = {
    texto: linhas.join('\n'),
    total: Number(total.toFixed(2)),
    quantidade: itens.length
  };
}

return [{
  json: {
    periodo: { start_date: trigger.start_date, end_date: trigger.end_date },
    categorias: compRows.map(r => ({
      category_id: r.category_id,
      planejado: Number(r.planejado),
      realizado: Number(r.realizado)
    })),
    lancamentos: lancRows.map(r => ({
      date: r.date,
      category_id: r.category_id,
      description: r.description,
      value: Number(r.value)
    })),
    detalhamento_por_categoria: detalhamentoPorCategoria
  }
}];
